begin;
create table if not exists public.service_variants (
 id bigint generated by default as identity primary key, created_at timestamptz not null default now(),
 clinic_id bigint not null references public.clinics(id) on delete restrict,
 service_id bigint not null references public.services(id) on delete cascade,
 name text not null, price numeric(12,2) not null check(price>=0),
 is_starting_from boolean not null default false, is_active boolean not null default true
);
create unique index if not exists service_variants_service_name_unique on public.service_variants(service_id,lower(name));
alter table public.treatment_items add column if not exists service_variant_id bigint;
alter table public.treatment_items add column if not exists unit_price numeric(12,2);
alter table public.treatment_items add column if not exists line_total numeric(12,2);
do $$ begin
 if not exists(select 1 from pg_constraint where conname='treatment_items_service_variant_id_fkey') then
  alter table public.treatment_items add constraint treatment_items_service_variant_id_fkey foreign key(service_variant_id) references public.service_variants(id) on delete set null;
 end if;
end $$;
alter table public.service_variants enable row level security;
drop policy if exists "Clinic users manage service variants" on public.service_variants;
create policy "Clinic users manage service variants" on public.service_variants for all to authenticated
using(exists(select 1 from public.user_clinic_access a where a.user_id=auth.uid() and a.clinic_id=service_variants.clinic_id))
with check(exists(select 1 from public.user_clinic_access a where a.user_id=auth.uid() and a.clinic_id=service_variants.clinic_id));
do $$
declare v_clinic_id bigint; v_branch_id bigint;
begin
 select id into v_clinic_id from public.clinics where code='PANTHERA' limit 1;
 select id into v_branch_id from public.branches where clinic_id=v_clinic_id and code='MAIN' limit 1;
 if v_clinic_id is null or v_branch_id is null then raise exception 'Panthera clinic or MAIN branch was not found'; end if;
 insert into public.services(clinic_id,name,code,category,default_price,duration_minutes,is_active,provider_type,price_starting_from)
 select v_clinic_id,x.name,x.code,x.name,0,30,true,'doctor',false from(values
 ('CONSULTATION','CONSULTATION'),('PICOWAY LASER','PICOWAY-LASER'),('FILLER','FILLER'),('LIPS FILLER','LIPS-FILLER'),
 ('BOTOX','BOTOX'),('SKIN BOOSTER','SKIN-BOOSTER'),('PEELING','PEELING'),('POLYLACTIC ACID','POLYLACTIC-ACID'),
 ('THREADS','THREADS'),('HAIR THERAPY','HAIR-THERAPY'),('FRAXIS','FRAXIS'))x(name,code)
 on conflict(clinic_id,code) do update set name=excluded.name,category=excluded.category,is_active=true,provider_type='doctor',default_price=0,price_starting_from=false;
 delete from public.staff_services ss using public.staff st where ss.staff_id=st.id and st.clinic_id=v_clinic_id
 and lower(trim(st.staff_name)) in('dr fatima alsatouf','dr maram');
 insert into public.staff_services(staff_id,service_id,is_active,duration_minutes)
 select st.id,s.id,true,s.duration_minutes from public.staff st cross join public.services s
 where st.clinic_id=v_clinic_id and s.clinic_id=v_clinic_id and lower(trim(st.staff_name)) in('dr fatima alsatouf','dr maram')
 and s.code in('CONSULTATION','PICOWAY-LASER','FILLER','LIPS-FILLER','BOTOX','SKIN-BOOSTER','PEELING','POLYLACTIC-ACID','THREADS','HAIR-THERAPY','FRAXIS')
 on conflict(staff_id,service_id) do update set is_active=true;
 insert into public.service_devices(service_id,device_id,is_required)
 select s.id,d.id,true from public.services s join public.devices d on d.clinic_id=s.clinic_id
 where s.clinic_id=v_clinic_id and ((s.code='PICOWAY-LASER' and d.code='PICOWAY') or(s.code='FRAXIS' and d.code='FRAXIS'))
 on conflict(service_id,device_id) do update set is_required=true;
 create temporary table zernio_variant_import(service_name text,service_code text,variant_name text,price numeric,starting boolean) on commit drop;
 insert into zernio_variant_import select service,code,name,price,starting from jsonb_to_recordset('[{"service":"CONSULTATION","code":"CONSULTATION","name":"CONSULTATION DERMATOLOGIST RESIDENT","price":200,"starting":false},{"service":"CONSULTATION","code":"CONSULTATION","name":"CONSULTATION CONSULTANT","price":200,"starting":false},{"service":"CONSULTATION","code":"CONSULTATION","name":"CONSULTATION SPECIALIST","price":200,"starting":false},{"service":"PICOWAY LASER","code":"PICOWAY-LASER","name":"LIPS WHITENING","price":1000,"starting":false},{"service":"PICOWAY LASER","code":"PICOWAY-LASER","name":"HYPERPIGMENTATION LARGE AREA","price":1500,"starting":true},{"service":"PICOWAY LASER","code":"PICOWAY-LASER","name":"HYPERPIGMENTATION SMALL AREA","price":1000,"starting":true},{"service":"PICOWAY LASER","code":"PICOWAY-LASER","name":"TATTOO REMOVAL LARGE AREA","price":1500,"starting":true},{"service":"PICOWAY LASER","code":"PICOWAY-LASER","name":"TATTOO REMOVAL SMALL AREA","price":799,"starting":true},{"service":"FILLER","code":"FILLER","name":"2ML RADIESSE","price":2800,"starting":false},{"service":"FILLER","code":"FILLER","name":"1ML JUVEDERM VOLUMA","price":1400,"starting":false},{"service":"FILLER","code":"FILLER","name":"1ML TEOSYAL RHA2","price":1400,"starting":false},{"service":"FILLER","code":"FILLER","name":"1ML TEOSYAL ULTRA DEEP","price":1400,"starting":false},{"service":"FILLER","code":"FILLER","name":"1ML BELOTERO","price":1400,"starting":false},{"service":"FILLER","code":"FILLER","name":"1ML RESTYLANE KYSS","price":1400,"starting":false},{"service":"FILLER","code":"FILLER","name":"HAYALORONIDASE","price":1000,"starting":false},{"service":"FILLER","code":"FILLER","name":"BODY FILLER HAYACORP 10ML","price":2800,"starting":false},{"service":"FILLER","code":"FILLER","name":"CAL HYBRID FILLER","price":1400,"starting":false},{"service":"FILLER","code":"FILLER","name":"1ML RADIESSE","price":1400,"starting":false},{"service":"FILLER","code":"FILLER","name":"1ML FILLER","price":1400,"starting":false},{"service":"FILLER","code":"FILLER","name":"1ML STYLAGE M","price":1400,"starting":false},{"service":"FILLER","code":"FILLER","name":"1ML EPTQ","price":1400,"starting":false},{"service":"FILLER","code":"FILLER","name":"1ML TEOSYAL REDENISTY 2","price":1400,"starting":false},{"service":"FILLER","code":"FILLER","name":"1ML DERMA STYLE","price":1100,"starting":false},{"service":"FILLER","code":"FILLER","name":"1ML JUVEDERM ULTRA DEEP4","price":1400,"starting":false},{"service":"LIPS FILLER","code":"LIPS-FILLER","name":"1ML TEOSYAL RHA3","price":1500,"starting":false},{"service":"LIPS FILLER","code":"LIPS-FILLER","name":"1 ML TEOYSYAL RH2","price":1500,"starting":false},{"service":"LIPS FILLER","code":"LIPS-FILLER","name":"1ML STYLAGE M","price":1500,"starting":false},{"service":"LIPS FILLER","code":"LIPS-FILLER","name":"1ML DERMA STYLE SMILE","price":1500,"starting":false},{"service":"LIPS FILLER","code":"LIPS-FILLER","name":"1ML RESTYLANE KYSS","price":1500,"starting":false},{"service":"BOTOX","code":"BOTOX","name":"MESO BOTOX ALLERGAN","price":1200,"starting":false},{"service":"BOTOX","code":"BOTOX","name":"MESO BOTOX DYSPORT","price":1200,"starting":false},{"service":"BOTOX","code":"BOTOX","name":"BOTOX GUMMY SMILE ALLERGAN","price":699,"starting":false},{"service":"BOTOX","code":"BOTOX","name":"BOTOX GUMMY SMILE DYSPORT","price":699,"starting":false},{"service":"BOTOX","code":"BOTOX","name":"BOTOX MASSETER MUSCLE ALLERGAN","price":1200,"starting":false},{"service":"BOTOX","code":"BOTOX","name":"BOTOX MASSETER MUSCLE DYSPORT","price":1200,"starting":false},{"service":"BOTOX","code":"BOTOX","name":"BOTOX FOREHEAD ALLERGAN","price":1200,"starting":false},{"service":"BOTOX","code":"BOTOX","name":"BOTOX FOREHEAD DYSPORT","price":1200,"starting":false},{"service":"BOTOX","code":"BOTOX","name":"BOTOX HYPERHYDROSIS ALLERGAN","price":2000,"starting":false},{"service":"BOTOX","code":"BOTOX","name":"BOTOX HYPERHYDROSIS DYSPORT","price":2000,"starting":false},{"service":"BOTOX","code":"BOTOX","name":"1ML BOTOX ALLERGAN","price":1200,"starting":false},{"service":"BOTOX","code":"BOTOX","name":"1ML BOTOX DYSPORT","price":1200,"starting":false},{"service":"BOTOX","code":"BOTOX","name":"1.5ML BOTOX ALLERGAN","price":1500,"starting":false},{"service":"BOTOX","code":"BOTOX","name":"1.5ML BOTOX DYSPORT","price":1500,"starting":false},{"service":"BOTOX","code":"BOTOX","name":"BOTOX FACE & NECK ALLERGAN","price":2000,"starting":false},{"service":"BOTOX","code":"BOTOX","name":"BOTOX FACE & NECK DYSPORT","price":2000,"starting":false},{"service":"BOTOX","code":"BOTOX","name":"BOTOX LARGE AREA ALLERGAN","price":1200,"starting":false},{"service":"BOTOX","code":"BOTOX","name":"BOTOX LARGE AREA DYSPORT","price":1200,"starting":false},{"service":"BOTOX","code":"BOTOX","name":"BOTOX SMALL AREA DYSPORT","price":699,"starting":false},{"service":"BOTOX","code":"BOTOX","name":"1.5ML BOTOX XIOMEN","price":1500,"starting":false},{"service":"BOTOX","code":"BOTOX","name":"1.5ML BOTOX ALLERGAN","price":1500,"starting":false},{"service":"BOTOX","code":"BOTOX","name":"1ML BOTOX XIOMEN","price":1200,"starting":false},{"service":"BOTOX","code":"BOTOX","name":"BOTOX SMALL AREA ALLERGAN","price":699,"starting":false},{"service":"BOTOX","code":"BOTOX","name":"1ML BOTOX ALLERGAN","price":1200,"starting":false},{"service":"BOTOX","code":"BOTOX","name":"1ML BOTOX DYSPORT","price":1200,"starting":false},{"service":"BOTOX","code":"BOTOX","name":"BARBIE BOTOX DYSPORT","price":2999,"starting":false},{"service":"BOTOX","code":"BOTOX","name":"1.5ML BOTOX DYSPORT","price":1500,"starting":false},{"service":"BOTOX","code":"BOTOX","name":"BARBIE BOTOX ALLERGAN","price":2999,"starting":false},{"service":"SKIN BOOSTER","code":"SKIN-BOOSTER","name":"DIVES","price":1700,"starting":false},{"service":"SKIN BOOSTER","code":"SKIN-BOOSTER","name":"JALUPRO SUPER HYDRO","price":1700,"starting":false},{"service":"SKIN BOOSTER","code":"SKIN-BOOSTER","name":"JALUPRO HMW","price":1700,"starting":false},{"service":"SKIN BOOSTER","code":"SKIN-BOOSTER","name":"EXOBAZ","price":1500,"starting":false},{"service":"SKIN BOOSTER","code":"SKIN-BOOSTER","name":"PLASMA MAGELLAN","price":2500,"starting":false},{"service":"SKIN BOOSTER","code":"SKIN-BOOSTER","name":"PLASMA PLUS","price":1500,"starting":false},{"service":"SKIN BOOSTER","code":"SKIN-BOOSTER","name":"INNOVYAL","price":1500,"starting":false},{"service":"SKIN BOOSTER","code":"SKIN-BOOSTER","name":"DERMAPEN","price":500,"starting":false},{"service":"SKIN BOOSTER","code":"SKIN-BOOSTER","name":"DERMAPEN WITH MESO","price":1500,"starting":false},{"service":"SKIN BOOSTER","code":"SKIN-BOOSTER","name":"TRANXAMIC ACID","price":1500,"starting":false},{"service":"SKIN BOOSTER","code":"SKIN-BOOSTER","name":"MESO","price":1500,"starting":false},{"service":"SKIN BOOSTER","code":"SKIN-BOOSTER","name":"EXOSOME","price":1500,"starting":false},{"service":"SKIN BOOSTER","code":"SKIN-BOOSTER","name":"SALMON","price":1700,"starting":false},{"service":"SKIN BOOSTER","code":"SKIN-BOOSTER","name":"HYDRO DELUXE","price":2500,"starting":false},{"service":"SKIN BOOSTER","code":"SKIN-BOOSTER","name":"PDRN","price":1700,"starting":false},{"service":"SKIN BOOSTER","code":"SKIN-BOOSTER","name":"PROFHILO","price":1700,"starting":false},{"service":"SKIN BOOSTER","code":"SKIN-BOOSTER","name":"JALUPRO CLASSIC","price":1700,"starting":false},{"service":"PEELING","code":"PEELING","name":"M.A.D PEELING","price":2000,"starting":false},{"service":"PEELING","code":"PEELING","name":"CIMEL","price":2000,"starting":false},{"service":"POLYLACTIC ACID","code":"POLYLACTIC-ACID","name":"5ML SCULPTRA","price":2500,"starting":false},{"service":"POLYLACTIC ACID","code":"POLYLACTIC-ACID","name":"STICOL VOLUME","price":3500,"starting":false},{"service":"POLYLACTIC ACID","code":"POLYLACTIC-ACID","name":"10ML SCULPTRA","price":3500,"starting":false},{"service":"THREADS","code":"THREADS","name":"APTOS THREAD","price":1500,"starting":false},{"service":"THREADS","code":"THREADS","name":"AMERICAN THREAD","price":1500,"starting":false},{"service":"THREADS","code":"THREADS","name":"GOLDEN THREAD","price":700,"starting":false},{"service":"HAIR THERAPY","code":"HAIR-THERAPY","name":"ACELL","price":6000,"starting":false},{"service":"HAIR THERAPY","code":"HAIR-THERAPY","name":"ALPACIA SMALL AREA","price":500,"starting":true},{"service":"HAIR THERAPY","code":"HAIR-THERAPY","name":"PLASMA PLUS","price":1500,"starting":false},{"service":"HAIR THERAPY","code":"HAIR-THERAPY","name":"PLASMA MAGELLAN","price":2500,"starting":false},{"service":"HAIR THERAPY","code":"HAIR-THERAPY","name":"EXOSOME 1ML","price":1500,"starting":false},{"service":"HAIR THERAPY","code":"HAIR-THERAPY","name":"MESO HAIR 1ML","price":1500,"starting":false},{"service":"HAIR THERAPY","code":"HAIR-THERAPY","name":"MINOXIDIL 1ML","price":1500,"starting":false},{"service":"HAIR THERAPY","code":"HAIR-THERAPY","name":"DUTASTERIDE 1ML","price":1500,"starting":false},{"service":"FRAXIS","code":"FRAXIS","name":"FRAXIS DUO","price":2000,"starting":false},{"service":"FRAXIS","code":"FRAXIS","name":"FRACTIONAL","price":1500,"starting":false},{"service":"FRAXIS","code":"FRAXIS","name":"MICRONEEDLING","price":1500,"starting":false},{"service":"FRAXIS","code":"FRAXIS","name":"SURGICAL LASER","price":500,"starting":true}]'::jsonb)
 as x(service text,code text,name text,price numeric,starting boolean);
 merge into public.service_variants target using(
  select distinct on (s.id, lower(i.variant_name))
    v_clinic_id clinic_id,s.id service_id,i.variant_name name,i.price,i.starting
  from zernio_variant_import i join public.services s on s.clinic_id=v_clinic_id and s.code=i.service_code
  order by s.id, lower(i.variant_name), i.variant_name
 )source on target.service_id=source.service_id and lower(target.name)=lower(source.name)
 when matched then update set price=source.price,is_starting_from=source.starting,is_active=true
 when not matched then insert(clinic_id,service_id,name,price,is_starting_from,is_active)
 values(source.clinic_id,source.service_id,source.name,source.price,source.starting,true);
end $$;
select 'main_services' check_name,count(*) row_count from public.services where clinic_id=1 and code in
('CONSULTATION','PICOWAY-LASER','FILLER','LIPS-FILLER','BOTOX','SKIN-BOOSTER','PEELING','POLYLACTIC-ACID','THREADS','HAIR-THERAPY','FRAXIS')
union all select 'service_variants',count(*) from public.service_variants where clinic_id=1
union all select 'starting_from_variants',count(*) from public.service_variants where clinic_id=1 and is_starting_from
union all select 'doctor_links',count(*) from public.staff_services ss join public.staff st on st.id=ss.staff_id
 where st.clinic_id=1 and lower(trim(st.staff_name)) in('dr fatima alsatouf','dr maram');
commit;
